/* -------------- */ /* Rent Outlier Users have on of the conditions below: */ /* 1 - More than 20 visits booked in the past 30 days */ /* 2 - More than 20 offers submitted in the past 30 days */ /* These values were obtained by 1) looking at the current distribution and 2) somewhat intuition into what "normal" users can do */ WITH rent_user_metrics AS (SELECT id_tenant_prospect AS id_user, COUNT(DISTINCT CASE WHEN NOT ts_booking_created IS NULL THEN id_house END) AS total_bookings, COUNT(DISTINCT CASE WHEN NOT ts_offer_submitted IS NULL THEN id_house END) AS total_offers FROM datalake_rent_flows.rent_flows WHERE NOT id_tenant_prospect IS NULL AND NOT id_house IS NULL AND (ts_booking_created BETWEEN DATE_ADD(CAST('{start_date}' AS DATE), STRUCT(days_past_30 AS days_past_30) * -1) AND CAST('{end_date}' AS DATE) OR ts_offer_submitted BETWEEN DATE_ADD(CAST('{start_date}' AS DATE), STRUCT(days_past_30 AS days_past_30) * -1) AND CAST('{end_date}' AS DATE)) GROUP BY id_tenant_prospect) SELECT id_user, total_bookings, total_offers FROM rent_user_metrics WHERE total_bookings >= 20 OR total_offers >= 20